-- models/marts/fct_events.sql
{{
  config(
    materialized='incremental',
    unique_key='event_id',
    incremental_strategy='merge',
    on_schema_change='append_new_columns'
  )
}}

select
    event_id,
    user_id,
    event_type,
    event_ts,
    payload
from {{ source('raw', 'events') }}

{% if is_incremental() %}
  -- Only runs on incremental builds (table already exists).
  -- Process events newer than what we already loaded, with a
  -- small lookback window to catch late-arriving rows.
  where event_ts > (select dateadd('hour', -3, max(event_ts)) from {{ this }})
{% endif %}
